CREATE INDEX `events_human_prompt_idx` ON `events` (`session_id`,`generation`,`type`,`ordinal`) WHERE (type = 'user_turn' AND CASE WHEN json_valid(payload) THEN json_extract(payload, '$.humanInitiated') = 1 OR (json_type(payload, '$.humanInitiated') IS NULL AND COALESCE(json_extract(payload, '$.attribution'), '') != 'app_authored') ELSE 0 END) OR type = 'reopened' OR (type = 'status' AND CASE WHEN json_valid(payload) THEN json_extract(payload, '$.state') IN ('ended', 'errored') ELSE 0 END);
